# [doc = " A dense table-based deterministic finite automaton (DFA)."] # [doc = ""] # [doc = " All dense DFAs have one or more start states, zero or more match states"] # [doc = " and a transition table that maps the current state and the current byte"] # [doc = " of input to the next state. A DFA can use this information to implement"] # [doc = " fast searching. In particular, the use of a dense DFA generally makes the"] # [doc = " trade off that match speed is the most valuable characteristic, even if"] # [doc = " building the DFA may take significant time *and* space. (More concretely,"] # [doc = " building a DFA takes time and space that is exponential in the size of the"] # [doc = " pattern in the worst case.) As such, the processing of every byte of input"] # [doc = " is done with a small constant number of operations that does not vary with"] # [doc = " the pattern, its size or the size of the alphabet. If your needs don't line"] # [doc = " up with this trade off, then a dense DFA may not be an adequate solution to"] # [doc = " your problem."] # [doc = ""] # [doc = " In contrast, a [`sparse::DFA`] makes the opposite"] # [doc = " trade off: it uses less space but will execute a variable number of"] # [doc = " instructions per byte at match time, which makes it slower for matching."] # [doc = " (Note that space usage is still exponential in the size of the pattern in"] # [doc = " the worst case.)"] # [doc = ""] # [doc = " A DFA can be built using the default configuration via the"] # [doc = " [`DFA::new`] constructor. Otherwise, one can"] # [doc = " configure various aspects via [`dense::Builder`](Builder)."] # [doc = ""] # [doc = " A single DFA fundamentally supports the following operations:"] # [doc = ""] # [doc = " 1. Detection of a match."] # [doc = " 2. Location of the end of a match."] # [doc = " 3. In the case of a DFA with multiple patterns, which pattern matched is"] # [doc = "    reported as well."] # [doc = ""] # [doc = " A notable absence from the above list of capabilities is the location of"] # [doc = " the *start* of a match. In order to provide both the start and end of"] # [doc = " a match, *two* DFAs are required. This functionality is provided by a"] # [doc = " [`Regex`](crate::dfa::regex::Regex)."] # [doc = ""] # [doc = " # Type parameters"] # [doc = ""] # [doc = " A `DFA` has one type parameter, `T`, which is used to represent state IDs,"] # [doc = " pattern IDs and accelerators. `T` is typically a `Vec<u32>` or a `&[u32]`."] # [doc = ""] # [doc = " # The `Automaton` trait"] # [doc = ""] # [doc = " This type implements the [`Automaton`] trait, which means it can be used"] # [doc = " for searching. For example:"] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::{dfa::{Automaton, dense::DFA}, HalfMatch, Input};"] # [doc = ""] # [doc = " let dfa = DFA::new(\"foo[0-9]+\")?;"] # [doc = " let expected = HalfMatch::must(0, 8);"] # [doc = " assert_eq!(Some(expected), dfa.try_search_fwd(&Input::new(\"foo12345\"))?);"] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [derive (Clone)] pub struct DFA < T > { # [doc = " The transition table for this DFA. This includes the transitions"] # [doc = " themselves, along with the stride, number of states and the equivalence"] # [doc = " class mapping."] tt : TransitionTable < T > , # [doc = " The set of starting state identifiers for this DFA. The starting state"] # [doc = " IDs act as pointers into the transition table. The specific starting"] # [doc = " state chosen for each search is dependent on the context at which the"] # [doc = " search begins."] st : StartTable < T > , # [doc = " The set of match states and the patterns that match for each"] # [doc = " corresponding match state."] # [doc = ""] # [doc = " This structure is technically only needed because of support for"] # [doc = " multi-regexes. Namely, multi-regexes require answering not just whether"] # [doc = " a match exists, but _which_ patterns match. So we need to store the"] # [doc = " matching pattern IDs for each match state. We do this even when there"] # [doc = " is only one pattern for the sake of simplicity. In practice, this uses"] # [doc = " up very little space for the case of one pattern."] ms : MatchStates < T > , # [doc = " Information about which states are \"special.\" Special states are states"] # [doc = " that are dead, quit, matching, starting or accelerated. For more info,"] # [doc = " see the docs for `Special`."] special : Special , # [doc = " The accelerators for this DFA."] # [doc = ""] # [doc = " If a state is accelerated, then there exist only a small number of"] # [doc = " bytes that can cause the DFA to leave the state. This permits searching"] # [doc = " to use optimized routines to find those specific bytes instead of using"] # [doc = " the transition table."] # [doc = ""] # [doc = " All accelerated states exist in a contiguous range in the DFA's"] # [doc = " transition table. See dfa/special.rs for more details on how states are"] # [doc = " arranged."] accels : Accels < T > , # [doc = " Any prefilter attached to this DFA."] # [doc = ""] # [doc = " Note that currently prefilters are not serialized. When deserializing"] # [doc = " a DFA from bytes, this is always set to `None`."] pre : Option < Prefilter > , # [doc = " The set of \"quit\" bytes for this DFA."] # [doc = ""] # [doc = " This is only used when computing the start state for a particular"] # [doc = " position in a haystack. Namely, in the case where there is a quit"] # [doc = " byte immediately before the start of the search, this set needs to be"] # [doc = " explicitly consulted. In all other cases, quit bytes are detected by"] # [doc = " the DFA itself, by transitioning all quit bytes to a special \"quit"] # [doc = " state.\""] quitset : ByteSet , # [doc = " Various flags describing the behavior of this DFA."] flags : Flags , }
